import os
from typing import Any, Dict, Optional

import boto3
from botocore.exceptions import ClientError


class CognitoPasswordResetError(Exception):
    pass


def start_password_reset(
    username: str,
    client_id: Optional[str] = None,
    region_name: Optional[str] = None,
    client_metadata: Optional[Dict[str, str]] = None,
    secret_hash: Optional[str] = None,
    analytics_metadata: Optional[Dict[str, str]] = None,
    user_context_data: Optional[Dict[str, str]] = None,
) -> Dict[str, Any]:
    if not username or not username.strip():
        raise ValueError("username is required")

    client_id = client_id or os.environ.get("COGNITO_CLIENT_ID")
    if not client_id:
        raise ValueError("COGNITO_CLIENT_ID is required")

    region_name = region_name or os.environ.get("AWS_REGION") or os.environ.get("AWS_DEFAULT_REGION")
    if not region_name:
        raise ValueError("AWS_REGION or AWS_DEFAULT_REGION is required")

    cognito = boto3.client("cognito-idp", region_name=region_name)

    params: Dict[str, Any] = {
        "ClientId": client_id,
        "Username": username,
    }

    if client_metadata:
        params["ClientMetadata"] = client_metadata
    if secret_hash:
        params["SecretHash"] = secret_hash
    if analytics_metadata:
        params["AnalyticsMetadata"] = analytics_metadata
    if user_context_data:
        params["UserContextData"] = user_context_data

    try:
        response = cognito.forgot_password(**params)
    except ClientError as e:
        error = e.response.get("Error", {})
        raise CognitoPasswordResetError(
            f"{error.get('Code', 'CognitoError')}: {error.get('Message', str(e))}"
        ) from e

    delivery = response.get("CodeDeliveryDetails", {})
    return {
        "provider": "aws_cognito",
        "operation": "forgot_password",
        "username": username,
        "delivery": {
            "destination": delivery.get("Destination"),
            "medium": delivery.get("DeliveryMedium"),
            "attribute_name": delivery.get("AttributeName"),
        },
    }
